<?php require __DIR__.'/../config/config.php';if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$stats=['Total users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Active users'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE account_status='active'")->fetchColumn(),'Conversations'=>(int)$pdo->query('SELECT COUNT(*) FROM conversations')->fetchColumn(),'Screenshot requests'=>(int)$pdo->query("SELECT COUNT(*) FROM screenshot_requests WHERE status='pending'")->fetchColumn(),'Recording requests'=>(int)$pdo->query("SELECT COUNT(*) FROM recording_requests WHERE status='pending'")->fetchColumn(),'Password requests'=>(int)$pdo->query("SELECT COUNT(*) FROM password_requests WHERE status='pending'")->fetchColumn()];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$kind=$_POST['kind']??'';$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$status=$action==='approve'?'approved':'rejected';$map=['screenshot'=>'screenshot_requests','recording'=>'recording_requests','password'=>'password_requests'];if(isset($map[$kind])&&$id){
 $t=$map[$kind];
 if($kind==='password' && $status==='approved'){
  $code=strtoupper(bin2hex(random_bytes(6)));
  $q=$pdo->prepare("UPDATE password_requests SET status='approved',reviewed_at=NOW(),reset_token_hash=?,reset_token_expires_at=DATE_ADD(NOW(),INTERVAL 30 MINUTE),reset_token_used_at=NULL WHERE id=?");
  $q->execute([password_hash($code,PASSWORD_DEFAULT),$id]);
  $_SESSION['password_reset_code_flash']=['id'=>$id,'code'=>$code];
 } else {
  $q=$pdo->prepare("UPDATE $t SET status=?,reviewed_at=NOW() WHERE id=?");$q->execute([$status,$id]);
 }
}if($kind==='user'&&$id){$q=$pdo->prepare("UPDATE users SET account_status=? WHERE id=?");$q->execute([$action==='suspend'?'suspended':'active',$id]);}header('Location: index.php');exit;}
$users=$pdo->query("SELECT u.id,u.username,u.full_name,u.account_status,u.created_at,(SELECT COUNT(*) FROM conversation_members cm WHERE cm.user_id=u.id) conversation_count FROM users u ORDER BY u.id DESC LIMIT 200")->fetchAll();
$resetFlash=$_SESSION['password_reset_code_flash']??null; unset($_SESSION['password_reset_code_flash']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/app.css"><title>RAAZ Admin</title></head><body><header class="top"><a class="logo">RAAZ<span>.</span> ADMIN</a><a href="../auth/logout.php">Logout</a></header><main class="admin"><h1>Control center</h1><?php if($resetFlash):?><div class="request"><strong>Password reset approved · Request #<?= (int)$resetFlash['id']?></strong><p>One-time code (valid for 30 minutes): <strong style="letter-spacing:2px"><?=e($resetFlash['code'])?></strong></p><p class="sub">Share this code with the verified account owner through a separate trusted channel. It will not be shown again.</p></div><?php endif?><div class="stats"><?php foreach($stats as $k=>$v):?><div class="stat"><small><?=e($k)?></small><strong><?=$v?></strong></div><?php endforeach?></div><h2>Users</h2><div class="tablewrap"><table><tr><th>User</th><th>Status</th><th>Conversations</th><th>Created</th><th>Action</th></tr><?php foreach($users as $x):?><tr><td><?=e($x['full_name'])?> <small>@<?=e($x['username'])?></small></td><td><?=e($x['account_status'])?></td><td><a class="mini" href="user-chats.php?user_id=<?=$x['id']?>"><?= (int)$x['conversation_count']?> · View</a></td><td><?=e($x['created_at'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="kind" value="user"><input type="hidden" name="id" value="<?=$x['id']?>"><button name="action" value="<?=$x['account_status']==='active'?'suspend':'activate'?>" class="mini"><?=$x['account_status']==='active'?'Suspend':'Reactivate'?></button></form></td></tr><?php endforeach?></table></div>
<?php foreach(['screenshot'=>'Screenshot requests','recording'=>'Recording requests','password'=>'Password recovery requests'] as $kind=>$title):$table=['screenshot'=>'screenshot_requests','recording'=>'recording_requests','password'=>'password_requests'][$kind];$rows=$pdo->query("SELECT * FROM $table WHERE status='pending' ORDER BY id DESC")->fetchAll();?><h2><?=e($title)?></h2><?php if(!$rows):?><p class="sub">No pending requests.</p><?php endif?><?php foreach($rows as $r):?><div class="request"><span>#<?=$r['id']?> · <?=e($r['username']??('User ID '.$r['user_id']))?><?php if($kind==='password'):?> · <?=e($r['full_name'])?> · <?=e($r['phone'])?><?php endif?> · <?=e($r['created_at'])?></span><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="kind" value="<?=e($kind)?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mini" name="action" value="approve">Approve</button><button class="mini danger" name="action" value="reject">Reject</button></form></div><?php endforeach;endforeach?>
</main></body></html>